class PhysiologyExtraQuestions3 {
  static final List<Question> questions = [
    // ============================================================
    // ASİT-BAZ DENGESİ (8 soru)
    // ============================================================
    Question(id: 'px3_001', category: 'physiology', subcategory: 'renal', type: 'test', difficulty: 'medium', questionText: 'Kan pH\'ının 7.35\'in altına düşmesine ne denir?', options: ['Alkaloz', 'Asidoz', 'Nötralizasyon', 'Tamponlama'], correctAnswer: 'Asidoz', explanation: 'Asidoz: pH < 7.35. Alkaloz: pH > 7.45. Normal: 7.35-7.45. Respiratuar asidoz: CO₂ birikimi. Metabolik asidoz: HCO₃⁻ kaybı veya asit birikimi.'),
    Question(id: 'px3_002', category: 'physiology', subcategory: 'renal', type: 'test', difficulty: 'hard', questionText: 'Diyabetik ketoasidoz hangi tip asidoza örnektir?', options: ['Respiratuar asidoz', 'Respiratuar alkaloz', 'Metabolik asidoz (artmış anyon açığı)', 'Metabolik alkaloz'], correctAnswer: 'Metabolik asidoz (artmış anyon açığı)', explanation: 'DKA\'da insülin eksikliği → yağ yıkımı → keton cisim üretimi → metabolik asidoz (artmış anyon açığı). Kussmaul solunumu kompansatuar mekanizmadır.'),
    Question(id: 'px3_003', category: 'physiology', subcategory: 'respiratory', type: 'test', difficulty: 'hard', questionText: 'KOAH hastasında CO₂ birikimi hangi tip asidoza yol açar?', options: ['Metabolik asidoz', 'Metabolik alkaloz', 'Respiratuar asidoz', 'Respiratuar alkaloz'], correctAnswer: 'Respiratuar asidoz', explanation: 'KOAH\'da alveolar ventilasyon azalır → CO₂ birikir → karbonik asit artar → respiratuar asidoz. Böbrekler HCO₃⁻ geri emilimini artırarak kompanse etmeye çalışır.'),
    Question(id: 'px3_004', category: 'physiology', subcategory: 'renal', type: 'test', difficulty: 'hard', questionText: 'Uzun süreli kusma hangi tip asit-baz bozukluğuna yol açar?', options: ['Metabolik asidoz', 'Metabolik alkaloz', 'Respiratuar asidoz', 'Respiratuar alkaloz'], correctAnswer: 'Metabolik alkaloz', explanation: 'Kusmada mide HCl\'si kaybedilir → H⁺ kaybı → metabolik alkaloz gelişir. Ayrıca dehidratasyon ve hipokalemi de eşlik eder.'),

    // ============================================================
    // ELEKTROLİT DENGESİ (8 soru)
    // ============================================================
    Question(id: 'px3_005', category: 'physiology', subcategory: 'renal', type: 'test', difficulty: 'medium', questionText: 'Hücre dışı sıvının en önemli katyonu hangisidir?', options: ['Potasyum (K⁺)', 'Sodyum (Na⁺)', 'Kalsiyum (Ca²⁺)', 'Magnezyum (Mg²⁺)'], correctAnswer: 'Sodyum (Na⁺)', explanation: 'Na⁺ hücre dışı sıvının başlıca katyonudur (135-145 mEq/L). Ozmolarite, sıvı dengesi ve sinir iletiminde kritik rol oynar. K⁺ ise hücre içinin başlıca katyonudur.'),
    Question(id: 'px3_006', category: 'physiology', subcategory: 'renal', type: 'test', difficulty: 'medium', questionText: 'Hücre içi sıvının en önemli katyonu hangisidir?', options: ['Sodyum (Na⁺)', 'Potasyum (K⁺)', 'Kalsiyum (Ca²⁺)', 'Klor (Cl⁻)'], correctAnswer: 'Potasyum (K⁺)', explanation: 'K⁺ hücre içi sıvının başlıca katyonudur (140 mEq/L hücre içi). İstirahat membran potansiyeli, kas kasılması ve kalp ritmi için kritiktir.'),
    Question(id: 'px3_007', category: 'physiology', subcategory: 'cardiovascular', type: 'test', difficulty: 'hard', questionText: 'Hiperkalemi (yüksek potasyum) kalp üzerinde en tehlikeli etkisi nedir?', options: ['Taşikardi', 'Kardiyak arrest (kalp durması)', 'Hipertansiyon', 'Kalp büyümesi'], correctAnswer: 'Kardiyak arrest (kalp durması)', explanation: 'Hiperkalemi (K⁺ > 5.5 mEq/L), kardiyak ileti bozukluklarına ve ventriküler fibrilasyona yol açabilir. EKG\'de sivri T dalgaları, geniş QRS, P kaybı görülür. Acil tedavi gerektirir.'),
    Question(id: 'px3_008', category: 'physiology', subcategory: 'endocrine', type: 'test', difficulty: 'hard', questionText: 'Hipokalsemide görülen Chvostek belirtisi nedir?', options: ['El krampı', 'Yüz siniri üzerine vurulduğunda yüz kaslarında kasılma', 'Ayak dorsiflefleksiyonu', 'Göz titremesi'], correctAnswer: 'Yüz siniri üzerine vurulduğunda yüz kaslarında kasılma', explanation: 'Chvostek belirtisi: N. facialis üzerine (kulak önü) vurulduğunda aynı taraf yüz kaslarında kasılma. Trousseau belirtisi: Tansiyon manşonu şişirildiğinde elde karpopedal spazm. Her ikisi hipokalsemiyi gösterir.'),

    // ============================================================
    // KLİNİK FİZYOLOJİ SENARYOLARI (10 soru)
    // ============================================================
    Question(id: 'px3_009', category: 'physiology', subcategory: 'cardiovascular', type: 'test', difficulty: 'hard', questionText: '55 yaşında erkek hasta göğüs ağrısı ile acile başvuruyor. EKG\'de ST elevasyonu saptanıyor. En olası tanı nedir?', options: ['Stabil angina', 'Akut miyokard infarktüsü (STEMI)', 'Perikardit', 'Pulmoner emboli'], correctAnswer: 'Akut miyokard infarktüsü (STEMI)', explanation: 'ST elevasyonlu miyokard infarktüsü (STEMI): Koroner arterin tam tıkanması → transmural iskemi → EKG\'de ST elevasyonu. Acil perkütan koroner girişim (PKG) veya trombolitik tedavi gerekir.'),
    Question(id: 'px3_010', category: 'physiology', subcategory: 'respiratory', type: 'test', difficulty: 'hard', questionText: '30 yaş kadın, nefes darlığı ve göğüs ağrısı. Bacakta şişlik ve kızarıklık var. D-dimer yüksek. En olası tanı nedir?', options: ['Pnömoni', 'Astım atağı', 'Pulmoner emboli', 'Pnömotoraks'], correctAnswer: 'Pulmoner emboli', explanation: 'DVT (bacak şişliği) + dispne + göğüs ağrısı + yüksek D-dimer → Pulmoner emboli düşündürür. BT pulmoner anjiyografi ile tanı doğrulanır. Antikoagülan tedavi başlanır.'),
    Question(id: 'px3_011', category: 'physiology', subcategory: 'endocrine', type: 'test', difficulty: 'medium', questionText: 'Kan şekeri 40 mg/dL olan bilinç bulanık hastada ilk yapılması gereken nedir?', options: ['İnsülin vermek', 'IV glukoz (%50 dekstroz) vermek', 'Oral antidiyabetik vermek', 'Kan kültürü almak'], correctAnswer: 'IV glukoz (%50 dekstroz) vermek', explanation: 'Hipoglisemi (KŞ < 70 mg/dL) acil bir durumdur. Bilinci kapalı hastaya IV %50 dekstroz, bilinci açık hastaya oral glukoz verilir. Glukagon IM de alternatiftir.'),
    Question(id: 'px3_012', category: 'physiology', subcategory: 'nervous', type: 'test', difficulty: 'hard', questionText: 'Ani başlayan şiddetli baş ağrısı ("hayatımın en kötü baş ağrısı") olan hastada en olası tanı nedir?', options: ['Migren', 'Tansiyon tipi baş ağrısı', 'Subaraknoid kanama', 'Sinüzit'], correctAnswer: 'Subaraknoid kanama', explanation: 'Ani başlangıçlı "thunderclap" baş ağrısı, subaraknoid kanamayı (SAK) düşündürür. En sık neden berry anevrizma rüptürüdür. BT ve LP ile tanı konur. Nöroşirürji konsültasyonu gerekir.'),
    Question(id: 'px3_013', category: 'physiology', subcategory: 'nervous', type: 'test', difficulty: 'medium', questionText: 'Glasgow Koma Skalası hangi üç parametreyi değerlendirir?', options: ['Ateş, nabız, tansiyon', 'Göz açma, sözel yanıt, motor yanıt', 'Solunum, dolaşım, bilinç', 'Refleks, duyu, motor'], correctAnswer: 'Göz açma, sözel yanıt, motor yanıt', explanation: 'GKS: Göz açma (1-4) + Sözel yanıt (1-5) + Motor yanıt (1-6) = 3-15 puan. 8 ve altı ağır koma (entübasyon endikasyonu). 15 puan tam bilinçli.'),

    // ============================================================
    // MİKROBİYOLOJİ BAZLI SORULAR (12 soru)
    // ============================================================
    Question(id: 'px3_014', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'easy', questionText: 'Antibiyotikler hangi tür patojenlere karşı etkilidir?', options: ['Virüsler', 'Bakteriler', 'Prionlar', 'Parazitler'], correctAnswer: 'Bakteriler', explanation: 'Antibiyotikler bakteri enfeksiyonlarında kullanılır. Virüslere karşı antiviral, mantarlara karşı antifungal, parazitlere karşı antiparaziter ilaçlar kullanılır.'),
    Question(id: 'px3_015', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Gram boyamada mor/mavi renk alan bakteriler hangi gruba aittir?', options: ['Gram negatif', 'Gram pozitif', 'Aside dirençli', 'Atipik'], correctAnswer: 'Gram pozitif', explanation: 'Gram pozitif bakteriler kristal viyole boyasını tutarak mor görünür (kalın peptidoglikan duvar). Gram negatifler safranin ile pembe/kırmızı boyanır (ince peptidoglikan + dış membran).'),
    Question(id: 'px3_016', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Staphylococcus aureus hangi tür enfeksiyonlara en sık neden olur?', options: ['İdrar yolu enfeksiyonu', 'Deri ve yumuşak doku enfeksiyonları', 'Menenjit', 'Sıtma'], correctAnswer: 'Deri ve yumuşak doku enfeksiyonları', explanation: 'S. aureus, deri enfeksiyonlarının (fronkül, apse, selülit, impetigo) ve yara enfeksiyonlarının en sık etkenidir. Ayrıca endokardit, osteomiyelit ve sepsis de yapabilir.'),
    Question(id: 'px3_017', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Escherichia coli en sık hangi enfeksiyona neden olur?', options: ['Pnömoni', 'Üriner sistem enfeksiyonu (ÜSE)', 'Menenjit', 'Tüberküloz'], correctAnswer: 'Üriner sistem enfeksiyonu (ÜSE)', explanation: 'E. coli, komplike olmayan üriner sistem enfeksiyonlarının (sistit, piyelonefrit) en sık etkenidir. Aynı zamanda ishal, sepsis ve neonatal menenjit de yapabilir.'),
    Question(id: 'px3_018', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'HIV virüsü hangi bağışıklık hücresini enfekte eder?', options: ['B lenfosit', 'Nötrofil', 'CD4+ T yardımcı lenfosit', 'Eozinofil'], correctAnswer: 'CD4+ T yardımcı lenfosit', explanation: 'HIV, CD4+ T yardımcı lenfositleri (ve makrofajları) enfekte edip yıkar. CD4 sayısı < 200/µL olduğunda AIDS gelişir ve fırsatçı enfeksiyonlar ortaya çıkar.'),
    Question(id: 'px3_019', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Helicobacter pylori enfeksiyonu hangi hastalıklarla ilişkilidir?', options: ['Pnömoni ve bronşit', 'Peptik ülser ve mide kanseri', 'Hepatit ve siroz', 'Üriner enfeksiyon'], correctAnswer: 'Peptik ülser ve mide kanseri', explanation: 'H. pylori, mide mukozasında yaşayan spiral gram negatif bakteridir. Gastrit, duodenal/gastrik ülser ve mide MALT lenfoma ve adenokarsinoma risk faktörüdür.'),
    Question(id: 'px3_020', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Mycobacterium tuberculosis\'in boyama yöntemi hangisidir?', options: ['Gram boyama', 'Ziehl-Neelsen (aside dirençli boyama)', 'PAS boyama', 'Giemsa boyama'], correctAnswer: 'Ziehl-Neelsen (aside dirençli boyama)', explanation: 'M. tuberculosis hücre duvarında mikolik asit içerdiği için Gram boyama ile boyanmaz. Ziehl-Neelsen (aside dirençli/ARB boyama) ile kırmızı boyanır.'),
    Question(id: 'px3_021', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Endokardit profilaksisinde diş prosedürleri öncesi hangi antibiyotik verilir?', options: ['Siprofloksasin', 'Amoksisilin', 'Metronidazol', 'Gentamisin'], correctAnswer: 'Amoksisilin', explanation: 'Yüksek riskli hastalarda (protez kapak, geçirilmiş endokardit) invaziv dental prosedürlerden 30-60 dk önce oral amoksisilin 2g verilir. Penisilin alerjisi varsa azitromisin kullanılır.'),

    // ============================================================
    // ACİL TIP SENARYOLARI (8 soru)
    // ============================================================
    Question(id: 'px3_022', category: 'physiology', subcategory: 'cardiovascular', type: 'test', difficulty: 'medium', questionText: 'Kardiyopulmoner resüsitasyon (KPR) sırasında göğüs kompresyon hızı dakikada kaç olmalıdır?', options: ['60-80', '80-100', '100-120', '120-140'], correctAnswer: '100-120', explanation: 'AHA 2020 kılavuzuna göre KPR\'de göğüs kompresyonu hızı 100-120/dk, derinlik 5-6 cm olmalıdır. Kompresyon/ventilasyon oranı 30:2 (tek kurtarıcı).'),
    Question(id: 'px3_023', category: 'physiology', subcategory: 'cardiovascular', type: 'test', difficulty: 'medium', questionText: 'Anafilaksik şokta ilk verilmesi gereken ilaç hangisidir?', options: ['Antihistamin', 'Kortikosteroid', 'İntramusküler adrenalin (epinefrin)', 'Salbutamol'], correctAnswer: 'İntramusküler adrenalin (epinefrin)', explanation: 'Anafilakside ilk ilaç IM adrenalin (0.3-0.5 mg, uyluğun anterolateral kısmına). Bronkodilatasyon, vazokonstriksiyon ve kardiyak stimülasyon sağlar. Antihistamin ve steroid yardımcıdır.'),
    Question(id: 'px3_024', category: 'physiology', subcategory: 'cardiovascular', type: 'test', difficulty: 'hard', questionText: 'Tansiyon pnömotoraksın acil tedavisi nedir?', options: ['Antibiyotik', 'İğne dekompresyon (2. interkostal aralık, midklavikuler hat)', 'Perikardiyosentez', 'Torakotomi'], correctAnswer: 'İğne dekompresyon (2. interkostal aralık, midklavikuler hat)', explanation: 'Tansiyon pnömotoraks hayatı tehdit eder. Acil tedavi: 2. interkostal aralık midklavikuler hattan kalın iğne ile dekompresyon. Sonra tüp torakostomi yapılır.'),
    Question(id: 'px3_025', category: 'physiology', subcategory: 'cardiovascular', type: 'test', difficulty: 'medium', questionText: 'Hipovolemik şokta (kanama) ilk sıvı resüsitasyonu ne ile yapılır?', options: ['%5 Dekstroz', 'İzotonik NaCl (%0.9) veya Ringer laktat', 'Hipotonik sıvı', 'Kolloid'], correctAnswer: 'İzotonik NaCl (%0.9) veya Ringer laktat', explanation: 'Hemorajik şokta ilk sıvı resüsitasyonu izotonik kristalloidlerle (SF veya RL) yapılır. Masif kanamada kan ürünleri (eritrosit süspansiyonu, TDP, trombosit) de verilir.'),
  ];
}

class PharmacologyExtraQuestions3 {
  static final List<Question> questions = [
    // ============================================================
