    Question(id: 'phx3_001', category: 'pharmacology', subcategory: 'analgesics', type: 'test', difficulty: 'medium', questionText: 'Morfin hangi reseptör üzerinden etki gösterir?', options: ['Beta-adrenerjik', 'Mü (µ) opioid reseptörü', 'GABA reseptörü', 'Dopamin reseptörü'], correctAnswer: 'Mü (µ) opioid reseptörü', explanation: 'Morfin ve diğer opioidler (kodein, fentanil, oksikodon) primer olarak mü (µ) opioid reseptörleri üzerinden analjezi, öfori ve solunum depresyonu yapar.'),
    Question(id: 'phx3_002', category: 'pharmacology', subcategory: 'analgesics', type: 'test', difficulty: 'hard', questionText: 'Opioid kullanımının en tehlikeli yan etkisi hangisidir?', options: ['Konstipasyon', 'Bulantı', 'Solunum depresyonu', 'Kaşıntı'], correctAnswer: 'Solunum depresyonu', explanation: 'Opioidlerin en tehlikeli yan etkisi solunum depresyonudur (beyin sapındaki solunum merkezini baskılar). Doz aşımında ölüme neden olabilir. Antidotu naloksondur.'),
    Question(id: 'phx3_003', category: 'pharmacology', subcategory: 'analgesics', type: 'test', difficulty: 'medium', questionText: 'İbuprofen ve naproksen hangi ilaç grubuna aittir?', options: ['Opioid', 'NSAİD (Non-steroidal anti-inflamatuar)', 'Kortikosteroid', 'Antibiyotik'], correctAnswer: 'NSAİD (Non-steroidal anti-inflamatuar)', explanation: 'İbuprofen ve naproksen NSAİD grubundandır. COX enzimini inhibe ederek prostaglandin sentezini azaltır. Ağrı, ateş ve iltihabı azaltır. GİS yan etkileri vardır.'),
    Question(id: 'phx3_004', category: 'pharmacology', subcategory: 'analgesics', type: 'test', difficulty: 'hard', questionText: 'COX-2 selektif inhibitör (selekoksib) COX-1 inhibitörlerinden hangi avantajı sağlar?', options: ['Daha güçlü ağrı kesici', 'Daha az gastrointestinal yan etki', 'Daha hızlı etki', 'Daha ucuz'], correctAnswer: 'Daha az gastrointestinal yan etki', explanation: 'COX-2 selektif inhibitörler, mide koruyucu prostoglandinleri üreten COX-1\'i koruyarak GİS yan etkilerini (ülser, kanama) azaltır. Ancak kardiyovasküler risk artışı vardır.'),

    // ============================================================
    // DİÜRETİKLER (6 soru)
    // ============================================================
    Question(id: 'phx3_005', category: 'pharmacology', subcategory: 'cardiovascular', type: 'test', difficulty: 'medium', questionText: 'Furosemid hangi tür diüretiktir?', options: ['Tiazid', 'Loop (kulp) diüretik', 'Potasyum tutucu', 'Ozmotik diüretik'], correctAnswer: 'Loop (kulp) diüretik', explanation: 'Furosemid, Henle kulpunun çıkan kalın kolunda Na⁺/K⁺/2Cl⁻ kotransportunu inhibe eden güçlü bir loop diüretiktir. Akut kalp yetmezliği ve ödemde kullanılır.'),
    Question(id: 'phx3_006', category: 'pharmacology', subcategory: 'cardiovascular', type: 'test', difficulty: 'medium', questionText: 'Spironolakton hangi tür diüretiktir?', options: ['Loop', 'Tiazid', 'Potasyum tutucu (aldosteron antagonisti)', 'Karbonik anhidraz inhibitörü'], correctAnswer: 'Potasyum tutucu (aldosteron antagonisti)', explanation: 'Spironolakton, aldosteron reseptörünü bloke ederek Na⁺ atılımını artırır ve K⁺ tutulumunu sağlar. Kalp yetmezliği ve hiperaldosteronizmde kullanılır. Jinekomasti yapabilir.'),

    // ============================================================
    // ANTİVİRAL VE ANTİFUNGAL (6 soru)
    // ============================================================
    Question(id: 'phx3_007', category: 'pharmacology', subcategory: 'antibiotics', type: 'test', difficulty: 'medium', questionText: 'Asiklovir hangi virüse karşı etkilidir?', options: ['HIV', 'Hepatit B', 'Herpes simpleks virüs (HSV)', 'İnfluenza'], correctAnswer: 'Herpes simpleks virüs (HSV)', explanation: 'Asiklovir, herpes grubu virüslere (HSV-1, HSV-2, VZV) karşı etkili antiviral ilaçtır. Viral timidin kinaz tarafından fosforilenerek aktifleşir ve viral DNA sentezini durdurur.'),
    Question(id: 'phx3_008', category: 'pharmacology', subcategory: 'antibiotics', type: 'test', difficulty: 'hard', questionText: 'HIV tedavisinde kullanılan HAART rejimi ne anlama gelir?', options: ['Tek ilaç tedavisi', 'Yüksek etkinlikli antiretroviral tedavi (en az 3 ilaç)', 'Antibiyotik kombinasyonu', 'Aşı tedavisi'], correctAnswer: 'Yüksek etkinlikli antiretroviral tedavi (en az 3 ilaç)', explanation: 'HAART (Highly Active Antiretroviral Therapy): En az 3 antiretroviral ilacın kombinasyonu. Viral replikasyonu baskılayarak viral yükü saptanamaz düzeye indirir.'),
    Question(id: 'phx3_009', category: 'pharmacology', subcategory: 'antibiotics', type: 'test', difficulty: 'medium', questionText: 'Flukonazol hangi tür enfeksiyonlarda kullanılır?', options: ['Bakteriyel', 'Viral', 'Fungal (mantar)', 'Paraziter'], correctAnswer: 'Fungal (mantar)', explanation: 'Flukonazol, azol grubu antifungal ilaçtır. Ergosterol sentezini inhibe ederek mantar hücre membranını bozar. Kandidiyaz ve kriptokokal menenjitte kullanılır.'),

    // ============================================================
    // İLAÇ ETKİLEŞİMLERİ (5 soru)
    // ============================================================
    Question(id: 'phx3_010', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Warfarin kullanan hastada K vitamini açısından zengin gıdaların (yeşil yapraklı sebzeler) etkisi nedir?', options: ['Warfarinin etkisini artırır', 'Warfarinin etkisini azaltır (kanama riski düşer)', 'Etkisi yoktur', 'Toksisiteye neden olur'], correctAnswer: 'Warfarinin etkisini azaltır (kanama riski düşer)', explanation: 'Warfarin K vitamini antagonistidir. K vitamini açısından zengin gıdalar (ıspanak, brokoli, lahana) warfarinin etkisini azaltır. INR düşer ve pıhtılaşma artar.'),
    Question(id: 'phx3_011', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'MAO inhibitörü kullanan hastada tiramin içeren gıdalar (peynir, şarap) neden tehlikelidir?', options: ['Hipoglisemi yapar', 'Hipertansif kriz gelişebilir', 'Böbrek yetmezliği yapar', 'Karaciğer toksisitesi yapar'], correctAnswer: 'Hipertansif kriz gelişebilir', explanation: 'MAO inhibitörleri tiramin metabolizmasını engeller. Biriken tiramin noradrenalin salınımını artırır → ciddi hipertansif kriz ("peynir reaksiyonu"). Kafa içi kanama riski.'),
    Question(id: 'phx3_012', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Metronidazol ile alkol birlikte alındığında ne olur?', options: ['Hiçbir şey', 'Disülfiram benzeri reaksiyon (bulantı, kusma, taşikardi)', 'Uyku hali', 'Hipertansiyon'], correctAnswer: 'Disülfiram benzeri reaksiyon (bulantı, kusma, taşikardi)', explanation: 'Metronidazol, aldehid dehidrogenaz enzimini inhibe eder. Alkolle birlikte alındığında asetaldehit birikir → şiddetli bulantı, kusma, karın ağrısı, kızarma, taşikardi.'),
  ];
}

class PathologyExtraQuestions3 {
  static final List<Question> questions = [
    // ============================================================
    // KANSER BİYOLOJİSİ (8 soru)
    // ============================================================
    Question(id: 'ptx3_001', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Onkogen nedir?', options: ['Tümör baskılayıcı gen', 'Hücre büyümesini uyaran mutasyona uğramış gen', 'DNA tamir geni', 'Apoptoz geni'], correctAnswer: 'Hücre büyümesini uyaran mutasyona uğramış gen', explanation: 'Onkogenler, proto-onkogenlerin mutasyona uğramış formlarıdır. Hücre büyümesini ve bölünmesini kontrol dışı uyarırlar. Örnekler: RAS, MYC, HER2, BCR-ABL.'),
    Question(id: 'ptx3_002', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Metastaz en sık hangi yollarla gerçekleşir?', options: ['Sadece kan yolu', 'Kan yolu (hematojen) ve lenf yolu (lenfojen)', 'Sadece direkt yayılım', 'Sadece lenf yolu'], correctAnswer: 'Kan yolu (hematojen) ve lenf yolu (lenfojen)', explanation: 'Metastaz yolları: 1) Lenfojen (lenf damarları ile, karsinomlar sık), 2) Hematojen (kan damarları ile, sarkomlar sık), 3) Transselomik (seröz boşluklar), 4) İmplantasyon.'),
    Question(id: 'ptx3_003', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Tümör belirteci CA-125 en çok hangi kanserle ilişkilidir?', options: ['Meme kanseri', 'Over (yumurtalık) kanseri', 'Prostat kanseri', 'Kolon kanseri'], correctAnswer: 'Over (yumurtalık) kanseri', explanation: 'CA-125, over kanserinde yükselen tümör belirtecidir. PSA: Prostat. CEA: Kolorektal. AFP: Hepatoselüler/germ hücre. CA 19-9: Pankreas. HCG: Koryokarsinom.'),
    Question(id: 'ptx3_004', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'BRCA1 ve BRCA2 gen mutasyonları hangi kanserlerin riskini artırır?', options: ['Akciğer ve mide kanseri', 'Meme ve over kanseri', 'Kolon ve rektum kanseri', 'Pankreas ve karaciğer kanseri'], correctAnswer: 'Meme ve over kanseri', explanation: 'BRCA1 ve BRCA2, DNA tamir genlerdir (tümör süpresör). Mutasyonları meme kanseri riskini %60-80\'e, over kanseri riskini %20-40\'a çıkarır.'),
    Question(id: 'ptx3_005', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Kanser tanısında kesin tanı yöntemi hangisidir?', options: ['Kan testi', 'Radyolojik görüntüleme', 'Biyopsi ve histopatolojik inceleme', 'Fizik muayene'], correctAnswer: 'Biyopsi ve histopatolojik inceleme', explanation: 'Kanser kesin tanısı, biyopsi ile alınan doku örneğinin patolog tarafından mikroskobik incelenmesiyle konur. Görüntüleme ve tümör belirteçleri destekleyicidir.'),

    // ============================================================
    // OTOİMMÜN VE ENFEKSİYON PATOLOJİSİ (7 soru)
    // ============================================================
    Question(id: 'ptx3_006', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Sistemik lupus eritematozus (SLE) hangi otoantikorla karakterizedir?', options: ['Anti-TPO', 'Anti-nükleer antikor (ANA) ve Anti-dsDNA', 'Anti-mitokondriyal', 'Anti-Smith (Sm)'], correctAnswer: 'Anti-nükleer antikor (ANA) ve Anti-dsDNA', explanation: 'SLE\'de ANA çok sensitif (%95+), anti-dsDNA ve anti-Sm çok spesifiktir. SLE çoklu organ tutulumu yapan kronik otoimmün hastalıktır. Kelebek döküntüsü (malar rash) tipiktir.'),
    Question(id: 'ptx3_007', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Romatoid artritte hedef doku hangisidir?', options: ['Deri', 'Sinovyal membran (eklem zarı)', 'Kemik iliği', 'Karaciğer'], correctAnswer: 'Sinovyal membran (eklem zarı)', explanation: 'Romatoid artrit, sinovyal membranın kronik otoimmün enflamasyonudur. Sinovyal hipertrofi (pannus) oluşur ve kıkırdak/kemik yıkımına neden olur. RF ve anti-CCP pozitiftir.'),
    Question(id: 'ptx3_008', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Multipl skleroz (MS) hangi yapıyı etkiler?', options: ['Periferik sinirler', 'MSS\'de miyelin kılıfı (demiyelinizasyon)', 'Kas dokusu', 'Eklemler'], correctAnswer: 'MSS\'de miyelin kılıfı (demiyelinizasyon)', explanation: 'MS, merkezi sinir sisteminde miyelin kılıfının otoimmün yıkımı (demiyelinizasyon) ile karakterizedir. Alevlenme-remisyon paterninde seyreder. Görme bozukluğu, güçsüzlük, ataksi görülür.'),
    Question(id: 'ptx3_009', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Çölyak hastalığının tetikleyicisi nedir?', options: ['Laktoz', 'Fruktoz', 'Gluten proteini', 'Kazein'], correctAnswer: 'Gluten proteini', explanation: 'Çölyak hastalığı, buğday/arpa/çavdardaki gluten proteinine karşı otoimmün yanıttır. İnce bağırsak villus atrofisi ve malabsorpsiyon yapar. Anti-tTG ve anti-endomisyum antikorları pozitiftir.'),
    Question(id: 'ptx3_010', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Sepsis nedir?', options: ['Lokal enfeksiyon', 'Enfeksiyona karşı vücudun düzensiz sistemik inflamatuar yanıtı', 'Alerjik reaksiyon', 'Otoimmün hastalık'], correctAnswer: 'Enfeksiyona karşı vücudun düzensiz sistemik inflamatuar yanıtı', explanation: 'Sepsis, enfeksiyona karşı vücudun abartılı ve düzensiz inflamatuar yanıtıdır. Organ disfonksiyonuna yol açar. Septik şok: Sepsis + refrakter hipotansiyon + laktat yüksekliği.'),
  ];
}
